import{_ as e,o as a,c as s,a2 as o}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{"title":"Installation"},"headers":[],"relativePath":"installation/index.md","filePath":"installation/index.md"}'),i={name:"installation/index.md"};function d(n,t,l,r,c,p){return a(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Fault can be built for source if you like, but the best way to install Fault is by <a href="https://github.com/Fault-lang/Fault/releases" target="_blank" rel="noreferrer">downloading the correct release for your machine</a>.</p><p>Once installed the model checker of Fault needs access to a SMT solver, otherwise Fault will default to generating SMT of models only. Microsoft&#39;s Z3 is the recommended solver at this time and <a href="https://github.com/Z3Prover/z3/releases" target="_blank" rel="noreferrer">can be downloaded here</a></p><p>Then in order for Fault to find your solver you need to set two configuration variables: <code>SOLVERCMD</code> (the solver command) and <code>SOLVERARG</code> (the argument it takes to read SMT from stdin).</p><p>The easiest way to do this is with the built-in <code>fault config</code> command, which writes to <code>~/.faultrc</code> so the settings persist across sessions:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solvercmd=z3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solverarg=-in</span></span></code></pre></div><p>You can verify the current config at any time by running <code>fault config</code> with no arguments.</p><p>Alternatively, you can set them as environment variables directly (e.g. in your shell profile):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export SOLVERCMD=&quot;z3&quot;</span></span>
<span class="line"><span>export SOLVERARG=&quot;-in&quot;</span></span></code></pre></div><p><strong>That&#39;s it!</strong> You should be able to run Fault now</p><h2 id="fault-tui" tabindex="-1">Fault TUI <a class="header-anchor" href="#fault-tui" aria-label="Permalink to &quot;Fault TUI&quot;">​</a></h2><p>Running <code>fault</code> with no arguments launches the interactive TUI. It walks you through compilation options in a full-screen terminal interface:</p><ol><li><strong>Setup</strong> — enter a file path and choose compilation options (mode, input format, output format)</li><li><strong>Progress</strong> — an animated spinner shows compilation status</li><li><strong>Results</strong> — scrollable output with vim-style navigation (<code>j</code>/<code>k</code> or <code>↑</code>/<code>↓</code>, <code>q</code> to quit)</li></ol><p>If compilation fails, the <strong>Error</strong> view shows the failure phase, a description, and a suggestion. From there you can retry, return to setup, or quit.</p><p><strong>TUI keybindings:</strong></p><table tabindex="0"><thead><tr><th>Context</th><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td>Global</td><td><code>Ctrl+C</code> / <code>Ctrl+Q</code></td><td>Quit</td></tr><tr><td>Global</td><td><code>Ctrl+T</code></td><td>Toggle light/dark theme</td></tr><tr><td>Setup</td><td><code>↑</code>/<code>↓</code>, <code>Enter</code></td><td>Navigate and select options</td></tr><tr><td>Results</td><td><code>↑</code>/<code>↓</code> or <code>j</code>/<code>k</code></td><td>Scroll output</td></tr><tr><td>Error</td><td><code>↑</code>/<code>↓</code> or <code>j</code>/<code>k</code>, <code>Enter</code></td><td>Navigate actions</td></tr><tr><td>Error</td><td><code>r</code> / <code>b</code> / <code>q</code></td><td>Retry / Back to setup / Quit</td></tr></tbody></table><h2 id="fault-command-line" tabindex="-1">Fault Command Line <a class="header-anchor" href="#fault-command-line" aria-label="Permalink to &quot;Fault Command Line&quot;">​</a></h2><p>When a file path is provided via <code>-f</code>, Fault runs in traditional CLI mode and prints results to stdout.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fault -f &lt;path&gt; [flags]</span></span>
<span class="line"><span>fault &lt;subcommand&gt; [flags]</span></span></code></pre></div><h3 id="flags" tabindex="-1">Flags <a class="header-anchor" href="#flags" aria-label="Permalink to &quot;Flags&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>-f, --file &lt;path&gt;</code></td><td><em>(required)</em></td><td>Path to the <code>.fspec</code> or <code>.fsystem</code> file to compile</td></tr><tr><td><code>-m, --mode &lt;mode&gt;</code></td><td><code>model</code></td><td>Stop the compiler at a milestone: <code>ast</code>, <code>ir</code>, <code>smt</code>, <code>template</code>, or <code>model</code></td></tr><tr><td><code>-i, --input &lt;format&gt;</code></td><td><code>fault</code></td><td>Input file format: <code>fault</code>, <code>ll</code>, or <code>smt2</code></td></tr><tr><td><code>--output &lt;format&gt;</code></td><td><code>text</code></td><td>Output format: <code>text</code> or <code>smt</code></td></tr><tr><td><code>--format &lt;name|path&gt;</code></td><td><code>default</code></td><td>Output template: <code>default</code>, <code>json</code>, <code>compact</code>, or a path to a Go template file</td></tr><tr><td><code>--complete</code></td><td>false</td><td>Verify that transitions to all defined states are specified in the model</td></tr><tr><td><code>--smt-threshold &lt;n&gt;</code></td><td>10000</td><td>Warn before sending SMT larger than <code>n</code> lines to the solver</td></tr><tr><td><code>--timeout &lt;ms&gt;</code></td><td>30000</td><td>Solver timeout in milliseconds (0 = no limit)</td></tr><tr><td><code>--memory-max-size &lt;MB&gt;</code></td><td>1096</td><td>Solver memory limit in MB (0 = no limit)</td></tr></tbody></table><h3 id="subcommands" tabindex="-1">Subcommands <a class="header-anchor" href="#subcommands" aria-label="Permalink to &quot;Subcommands&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Subcommand</th><th>Description</th></tr></thead><tbody><tr><td><code>fault lint -f &lt;file&gt; [--warn-only]</code></td><td>Parse and type-check only; collects all errors without compiling</td></tr><tr><td><code>fault config [--solvercmd=z3] [--solverarg=-in]</code></td><td>Read or write <code>~/.faultrc</code>; no flags prints current config</td></tr><tr><td><code>fault update</code></td><td>Download and install the latest release from GitHub</td></tr><tr><td><code>fault render -f &lt;tmpl&gt; [--params &lt;json&gt;]</code></td><td>Substitute parameters into a <code>.smt2.tmpl</code> and run model checking</td></tr></tbody></table><p>Any binary named <code>fault-&lt;name&gt;</code> on your PATH is automatically available as <code>fault &lt;name&gt;</code>.</p><p><strong>Examples:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run the full model checker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/battery.fspec</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Inspect the AST</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/battery.fspec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ast</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate SMT output only (no solver needed)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/battery.fspec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Type-check without compiling</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/battery.fspec</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Get JSON output (warnings go to stderr, result to stdout)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/battery.fspec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><p>If <code>SOLVERCMD</code> or <code>SOLVERARG</code> are not set when running in <code>model</code> mode, Fault will return an error. Use <code>-m smt</code> with <code>--output smt</code> to inspect the generated SMT without a solver.</p>`,27)])])}const m=e(i,[["render",d]]);export{u as __pageData,m as default};
